	// Java handling of frame, drawing, mouse, key, target, and idling	//------------------------------------------------------------------------------------	void JavaDraw(CRegion_AC visibleRegion);		void JavaMouseEvent(const CPoint_AC& theMouse, short modifiers);		void JavaKeyEvent(char asciiChar, char keyCode, short modifiers);		void JavaBecameTarget();		void JavaResignedTarget();		void JavaIdle();	virtual void JavaAdjustVisibility() const = 0;		// Must be implemented in subclasses.		// JMSetFrameVisibility() should be called from this method.	//------------------------------------------------------------------------------------	// Handling requests polymorphically from callbacks	//------------------------------------------------------------------------------------			virtual void* SetupPortRequest();		virtual void RestorePortRequest(void* refCon);		virtual bool ResizeRequest(CRect_AC& desiredRect);		virtual void ShowHideRequest(bool showIt);		virtual void SetTitleRequest(const CString_AC& title);		virtual void CheckUpdateRequest();		virtual void InvalRectRequest(const CRect_AC& invalidRect);		virtual void StatusMessageRequest(const CString_AC& statusMsg);		virtual void ReleaseFrameRequest();	//------------------------------------------------------------------------------------	// Getting a reference to Java view, given a frame ref or context ref.	//------------------------------------------------------------------------------------	static MJavaView_AC* JavaViewFromFrameRef(JMFrameRef ref);		static MJavaView_AC* JavaViewFromContextRef(JMAWTContextRef ref);	//------------------------------------------------------------------------------------	// CALLBACKS	//------------------------------------------------------------------------------------	virtual void SetupCallbacks(JMFrameCallbacks* callbacks);private:	JMAWTContextRef fContext;	JMFrameRef fFrame;	bool fDeferredActivate;};//------------------------------------------------------------------------------------// CALLBACKS//------------------------------------------------------------------------------------extern "C" void WinInvalRectRequestProc(JMFrameRef ref, const Rect* r);extern "C" Boolean WinSetFrameSizeRequestProc(JMFrameRef ref, const Rect* r);extern "C" void WinShowHideRequestProc(JMFrameRef ref, Boolean showIt);extern "C" void WinSetTitleRequestProc(JMFrameRef ref, JMTextRef title);extern "C" void WinCheckUpdateRequestProc(JMFrameRef ref);extern "C" void WinResizeRequestProc(JMFrameRef ref, const Rect* desired);extern "C" void WinFrameReorderRequestProc(JMFrameRef ref, enum ReorderRequest theRequest);	extern "C" void WinSetResizeableRequestProc(JMFrameRef frame, Boolean resizeable);#endif // __MJavaView_AC__